#!/usr/bin/env node
/**
 * Generates `web/src/lib/taxonomy.generated.ts` from the AgentHorde taxonomy
 * SoT snapshot at `shared/taxonomy/taxonomy.json`.
 *
 * The snapshot itself is produced by
 *   cd agents/shared/agenthorde_common && python -m scripts.export_taxonomy \
 *     --out ../../../shared/taxonomy/taxonomy.json
 *
 * Pass `--check` to fail with a non-zero exit code if the on-disk file does
 * not match what would be emitted (used by CI to catch stale generated files).
 */

import { promises as fs } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const REPO_ROOT = path.resolve(__dirname, '../..');
const INPUT = path.join(REPO_ROOT, 'shared/taxonomy/taxonomy.json');
const OUTPUT = path.join(REPO_ROOT, 'web/src/lib/taxonomy.generated.ts');

const args = new Set(process.argv.slice(2));
const CHECK = args.has('--check');

function pascal(s) {
  if (!s) return '';
  if (!/[_\-./ ]/.test(s) && /^[A-Z][A-Za-z0-9]*$/.test(s)) {
    return s;
  }
  return s
    .split(/[_\-./ ]+/)
    .filter(Boolean)
    .map(p => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join('');
}

function quoted(v) {
  return JSON.stringify(v);
}

function asConstObject(entries, indent = '  ') {
  const lines = entries.map(([k, v]) => `${indent}${k}: ${v},`);
  return `{\n${lines.join('\n')}\n}`;
}

function buildHeader() {
  return [
    '/* eslint-disable */',
    '// Code generated by web/scripts/generate-taxonomy.mjs from shared/taxonomy/taxonomy.json',
    '// Single source of truth: agents/shared/agenthorde_common/agenthorde_common/canonicalizer/taxonomy.py',
    '// DO NOT EDIT BY HAND. Re-run `npm run gen:taxonomy` after refreshing the JSON snapshot.',
    '',
  ].join('\n');
}

function emit(payload) {
  const out = [];
  out.push(buildHeader());
  out.push(`export const SCHEMA_VERSION = ${quoted(payload.schema_version)};`);
  out.push('');

  // ---- Fragment classes ----
  const allFC = [...payload.fragment_classes.all].sort();
  const structFC = new Set(payload.fragment_classes.structural);
  const decisionFC = new Set(payload.fragment_classes.decision_layer);

  out.push('// ---- Fragment classes ----');
  out.push(
    `export const FRAGMENT_CLASS = ${asConstObject(
      allFC.map(c => [pascal(c), quoted(c)])
    )} as const;`
  );
  out.push('export type FragmentClass = (typeof FRAGMENT_CLASS)[keyof typeof FRAGMENT_CLASS];');
  out.push(
    `export const FRAGMENT_CLASSES: readonly FragmentClass[] = [${allFC
      .map(c => `FRAGMENT_CLASS.${pascal(c)}`)
      .join(', ')}] as const;`
  );
  out.push(
    `export const STRUCTURAL_FRAGMENT_CLASSES: ReadonlySet<FragmentClass> = new Set([${[...structFC]
      .sort()
      .map(c => `FRAGMENT_CLASS.${pascal(c)}`)
      .join(', ')}]);`
  );
  out.push(
    `export const DECISION_LAYER_FRAGMENT_CLASSES: ReadonlySet<FragmentClass> = new Set([${[...decisionFC]
      .sort()
      .map(c => `FRAGMENT_CLASS.${pascal(c)}`)
      .join(', ')}]);`
  );
  out.push('');

  // ---- Layers ----
  const layers = new Set();
  for (const arr of Object.values(payload.relations.allowed_layers)) {
    for (const l of arr) layers.add(l);
  }
  const sortedLayers = [...layers].sort();
  out.push('// ---- Supergraph layers ----');
  out.push(
    `export const LAYER = ${asConstObject(
      sortedLayers.map(l => [pascal(l), quoted(l)])
    )} as const;`
  );
  out.push('export type Layer = (typeof LAYER)[keyof typeof LAYER];');
  out.push(
    `export const LAYERS: readonly Layer[] = [${sortedLayers
      .map(l => `LAYER.${pascal(l)}`)
      .join(', ')}] as const;`
  );
  out.push('');

  const sectionSet = new Set(Object.values(payload.relations.layer_sections));
  const sortedSections = [...sectionSet].sort();
  out.push('// ---- Layer sections (topical buckets) ----');
  out.push(
    `export const LAYER_SECTION = ${asConstObject(
      sortedSections.map(s => [pascal(s), quoted(s)])
    )} as const;`
  );
  out.push('export type LayerSection = (typeof LAYER_SECTION)[keyof typeof LAYER_SECTION];');
  out.push('');

  // ---- Relation names ----
  const relNames = [...payload.relations.names].sort();
  out.push('// ---- Relation names ----');
  out.push(
    `export const RELATION = ${asConstObject(
      relNames.map(n => [pascal(n), quoted(n)])
    )} as const;`
  );
  out.push('export type RelationName = (typeof RELATION)[keyof typeof RELATION];');
  out.push(
    `export const RELATION_NAMES: readonly RelationName[] = [${relNames
      .map(n => `RELATION.${pascal(n)}`)
      .join(', ')}] as const;`
  );
  out.push('');

  // ---- Relation -> allowed layers ----
  out.push('export const RELATION_ALLOWED_LAYERS: Readonly<Record<RelationName, readonly Layer[]>> = {');
  for (const n of relNames) {
    const lyrs = [...(payload.relations.allowed_layers[n] || [])].sort();
    out.push(
      `  [RELATION.${pascal(n)}]: [${lyrs.map(l => `LAYER.${pascal(l)}`).join(', ')}],`
    );
  }
  out.push('};');
  out.push('');

  out.push('export const RELATION_LAYER_SECTION: Readonly<Record<RelationName, LayerSection>> = {');
  for (const n of relNames) {
    const sec = payload.relations.layer_sections[n];
    if (!sec) continue;
    out.push(`  [RELATION.${pascal(n)}]: LAYER_SECTION.${pascal(sec)},`);
  }
  out.push('};');
  out.push('');

  // ---- Endpoint kinds & blacklist ----
  out.push('export interface EndpointKindRow {');
  out.push('  readonly from: FragmentClass;');
  out.push('  readonly to: FragmentClass;');
  out.push('  readonly kind: string;');
  out.push('}');
  out.push('');
  out.push('export const RELATION_ENDPOINT_KINDS: Readonly<Partial<Record<RelationName, readonly EndpointKindRow[]>>> = {');
  const kindRelNames = Object.keys(payload.relations.endpoint_kinds).sort();
  for (const n of kindRelNames) {
    const rows = [...payload.relations.endpoint_kinds[n]].sort((a, b) => {
      if (a.from !== b.from) return a.from < b.from ? -1 : 1;
      if (a.to !== b.to) return a.to < b.to ? -1 : 1;
      return a.kind < b.kind ? -1 : a.kind > b.kind ? 1 : 0;
    });
    out.push(`  [RELATION.${pascal(n)}]: [`);
    for (const r of rows) {
      out.push(
        `    { from: FRAGMENT_CLASS.${pascal(r.from)}, to: FRAGMENT_CLASS.${pascal(r.to)}, kind: ${quoted(r.kind)} },`
      );
    }
    out.push('  ],');
  }
  out.push('};');
  out.push('');

  out.push('export interface EndpointPair {');
  out.push('  readonly from: FragmentClass;');
  out.push('  readonly to: FragmentClass;');
  out.push('}');
  out.push('');
  out.push('export const RELATION_ENDPOINT_BLACKLIST: Readonly<Partial<Record<RelationName, readonly EndpointPair[]>>> = {');
  const blRelNames = Object.keys(payload.relations.endpoint_blacklist).sort();
  for (const n of blRelNames) {
    const rows = [...payload.relations.endpoint_blacklist[n]].sort((a, b) => {
      if (a.from !== b.from) return a.from < b.from ? -1 : 1;
      return a.to < b.to ? -1 : a.to > b.to ? 1 : 0;
    });
    out.push(`  [RELATION.${pascal(n)}]: [`);
    for (const r of rows) {
      out.push(
        `    { from: FRAGMENT_CLASS.${pascal(r.from)}, to: FRAGMENT_CLASS.${pascal(r.to)} },`
      );
    }
    out.push('  ],');
  }
  out.push('};');
  out.push('');

  // ---- Subtype enums ----
  out.push('// ---- Subtype enums ----');
  const enumNames = Object.keys(payload.subtype_enums).sort();
  for (const name of enumNames) {
    const blk = payload.subtype_enums[name];
    const values = [...blk.values].sort();
    if (blk.description) {
      out.push(`/** ${blk.description} */`);
    }
    out.push(
      `export const ${name} = ${asConstObject(
        values.map(v => [pascal(v), quoted(v)])
      )} as const;`
    );
    out.push(`export type ${name} = (typeof ${name})[keyof typeof ${name}];`);
    out.push(
      `export const ${name}Values: readonly ${name}[] = [${values
        .map(v => `${name}.${pascal(v)}`)
        .join(', ')}] as const;`
    );
    out.push('');
  }

  // ---- Attribute spec & keys ----
  out.push('// ---- Attribute spec ----');
  out.push('export interface AttributeSpec {');
  out.push('  readonly name: string;');
  out.push('  readonly carrier: string;');
  out.push('  readonly applies_to: readonly string[];');
  out.push('  readonly type: string;');
  out.push('  readonly required: boolean;');
  out.push('  readonly description: string;');
  out.push('}');
  out.push('');
  out.push('export const ATTRIBUTE_SPECS: readonly AttributeSpec[] = [');
  for (const s of payload.attribute_spec) {
    out.push(
      `  { name: ${quoted(s.name)}, carrier: ${quoted(s.carrier)}, applies_to: [${(s.applies_to || [])
        .map(quoted)
        .join(', ')}], type: ${quoted(s.type)}, required: ${s.required}, description: ${quoted(
        s.description
      )} },`
    );
  }
  out.push('];');
  out.push('');

  // De-duplicated attribute key constants.
  const seen = new Set();
  const uniqKeys = [];
  for (const s of payload.attribute_spec) {
    if (seen.has(s.name)) continue;
    seen.add(s.name);
    uniqKeys.push(s.name);
  }
  uniqKeys.sort();
  out.push('export const ATTR_KEY = {');
  for (const k of uniqKeys) {
    out.push(`  ${pascal(k)}: ${quoted(k)},`);
  }
  out.push('} as const;');
  out.push('export type AttrKey = (typeof ATTR_KEY)[keyof typeof ATTR_KEY];');
  out.push('');

  // ---- Incoterms ----
  const incos = [...payload.incoterms].sort();
  out.push('// ---- Incoterms 2020 ----');
  out.push(
    `export const INCOTERMS_2020: readonly string[] = [${incos.map(quoted).join(', ')}] as const;`
  );
  out.push('');

  // ---- Sanctions regimes ----
  out.push('export interface SanctionsRegimeSpec {');
  out.push('  readonly canonical_path: string;');
  out.push('  readonly label: string;');
  out.push('  readonly jurisdiction_iso2: string;');
  out.push('  readonly aliases: readonly string[];');
  out.push('}');
  out.push('');
  out.push('export const SANCTIONS_REGIMES: Readonly<Record<string, SanctionsRegimeSpec>> = {');
  const regimeCodes = Object.keys(payload.sanctions_regimes).sort();
  for (const code of regimeCodes) {
    const spec = payload.sanctions_regimes[code];
    out.push(
      `  ${quoted(code)}: { canonical_path: ${quoted(spec.canonical_path)}, label: ${quoted(
        spec.label
      )}, jurisdiction_iso2: ${quoted(spec.jurisdiction_iso2)}, aliases: [${(spec.aliases || [])
        .map(quoted)
        .join(', ')}] },`
    );
  }
  out.push('};');
  out.push('');

  return out.join('\n');
}

async function main() {
  const raw = await fs.readFile(INPUT, 'utf8');
  const payload = JSON.parse(raw);
  const rendered = emit(payload);

  if (CHECK) {
    let existing = '';
    try {
      existing = await fs.readFile(OUTPUT, 'utf8');
    } catch (err) {
      if (err.code === 'ENOENT') {
        console.error(`generate-taxonomy: --check failed; ${OUTPUT} does not exist.`);
        process.exit(2);
      }
      throw err;
    }
    if (existing !== rendered) {
      console.error(
        `generate-taxonomy: --check failed; ${OUTPUT} is stale.\n` +
          `Run \`npm run gen:taxonomy\` (after refreshing ${path.relative(REPO_ROOT, INPUT)}) and commit the result.`
      );
      process.exit(2);
    }
    return;
  }

  await fs.mkdir(path.dirname(OUTPUT), { recursive: true });
  await fs.writeFile(OUTPUT, rendered, 'utf8');
  console.log(`generate-taxonomy: wrote ${path.relative(REPO_ROOT, OUTPUT)} (${rendered.length} bytes)`);
}

main().catch(err => {
  console.error('generate-taxonomy: fatal', err);
  process.exit(1);
});
